const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const dateOnly=(d:Date)=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const escapeHtml=(v:any)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const formatUSDate=(value:any)=>{if(!value)return new Intl.DateTimeFormat('en-US',{month:'2-digit',day:'2-digit',year:'numeric'}).format(new Date());const parts=String(value).slice(0,10).split('-');if(parts.length===3)return `${parts[1]}/${parts[2]}/${parts[0]}`;return new Intl.DateTimeFormat('en-US',{month:'2-digit',day:'2-digit',year:'numeric'}).format(new Date(value))};
const recipeColumnLabels:Record<string,string>={name:'Recipe Name',category:'Category',yield_amount:'Yield Amount',yield_unit:'Yield Unit',ingredients_text:'Ingredients',product_id:'Related Product',instructions:'Preparation Instructions',prep_minutes:'Prep Time',temperature:'Oven Temperature',notes:'Notes'};
const formatUSTime=(value:any)=>{if(!value)return '—';const m=String(value).match(/^(\d{1,2}):(\d{2})/);if(!m)return String(value);const h=Number(m[1]);return `${h%12||12}:${m[2]} ${h>=12?'PM':'AM'}`};
const displayValue=(key:string,value:any)=>{if(value===null||value===undefined||value==='')return '—';if(['production_date','entry_date','hire_date','shift_date','label_date'].includes(key))return formatUSDate(value);if(['start_time','end_time'].includes(key))return formatUSTime(value);if(['created_at','updated_at'].includes(key))return new Intl.DateTimeFormat('en-US',{dateStyle:'short',timeStyle:'short'}).format(new Date(value));return String(value)};

