 useEffect(()=>{let mounted=true;supabase.auth.getSession().then(({data})=>{if(mounted){setSession(data.session);setAuthReady(true)}}).catch(()=>{if(mounted)setAuthReady(true)});const {data:{subscription}}=supabase.auth.onAuthStateChange((_event,s)=>setSession(s));return()=>{mounted=false;subscription.unsubscribe()}},[]);
 useEffect(()=>{let mounted=true;async function getProfile(){if(!session?.user){setProfile(null);return}const {data,error}=await supabase.from('profiles').select('id,full_name,email,role,active').eq('id',session.user.id).maybeSingle();if(!mounted)return;if(error){setNotice({type:'error',text:'No se pudo leer el perfil: '+error.message});setProfile(null)}else if(!data){setProfile(null);setNotice({type:'error',text:'El usuario no tiene perfil en public.profiles. Ejecuta el schema y revisa el trigger de usuarios.'})}else if(!data.active){setProfile(data);setNotice({type:'error',text:'Esta cuenta está desactivada. Contacta al superadministrador.'})}else setProfile(data)}getProfile();return()=>{mounted=false}},[session]);
 const loadRows=useCallback(async():Promise<boolean>=>{if(!section.table){setRows([]);return true}if(section.table==='products'&&!selectedModuleId){setRows([]);return true}setBusy(true);try{let q=supabase.from(section.table).select('*').limit(1000);if(section.table==='products'){q=q.eq('active',true);q=selectedModuleId==='__unassigned__'?q.is('module_id',null):q.eq('module_id',selectedModuleId)}if(section.table==='employee_shifts')q=q.order('shift_date',{ascending:true});else q=q.order('created_at',{ascending:false});const {data,error}=await q;if(error)throw error;setRows(data||[]);return true}catch(e:any){setRows([]);setNotice({type:'error',text:`No se pudieron cargar ${sectionTitle}: ${e.message||'Error desconocido'}. Revisa permisos RLS y columnas.`});return false}finally{setBusy(false)}},[section,selectedModuleId]);
