 useEffect(()=>{if(!isAdmin)return;let alive=true;async function counts(){const names=['products','suppliers','recipes','final_products'] as const;const result=await Promise.all(names.map(name=>supabase.from(name).select('id',{count:'exact',head:true})));if(!alive)return;const next:any={};names.forEach((name,i)=>next[name]=result[i].count??0);setMetrics(prev=>({...prev,...next}))}counts();return()=>{alive=false}},[isAdmin,session]);
