 async function remove(row:any){
  const isProduct=section.table==='products';
  if(!confirm(isProduct?'¿Retirar este producto del inventario? Si tiene movimientos, se conservará el historial y el producto quedará inactivo.':'¿Eliminar este registro? Esta acción no se puede deshacer.'))return;
  setBusy(true);try{
   const {error}=await supabase.from(section.table).delete().eq('id',row.id);
   if(error){
    const fkBlocked=isProduct&&(/foreign key|violates.*constraint|product_id.*inventory_movements|inventory_movements.*product_id/i.test(error.message||''));
    if(!fkBlocked)throw error;
    const {error:deactivateError}=await supabase.from('products').update({active:false,is_active:false,updated_at:new Date().toISOString()}).eq('id',row.id);
    if(deactivateError)throw new Error(`No se pudo eliminar físicamente ni retirar el producto: ${deactivateError.message}`);
    setNotice({type:'ok',text:'Producto retirado del inventario. Se conservaron sus movimientos anteriores.'});
   }else setNotice({type:'ok',text:isProduct?'Producto eliminado correctamente.':'Registro eliminado.'});
   if(isProduct){
    const {data:prods,error:prodsError}=await supabase.from('products').select('id,name,name_es,name_en,unit_id,unit,stock,module_id,active,is_active').eq('active',true).order('name');
    if(prodsError)throw prodsError;setLookupProducts(prods||[]);
   }
   await loadRows();
  }catch(e:any){setNotice({type:'error',text:'No se pudo eliminar: '+(e.message||'Error desconocido')})}finally{setBusy(false)}
 }
 function setMovementDraft(productId:string,key:'entry'|'exit',value:string){setMovementDrafts(prev=>({...prev,[productId]:{entry:prev[productId]?.entry||'',exit:prev[productId]?.exit||'', [key]:value}}))}
 const movementProducts=lookupProducts.filter((p:any)=>(p.active!==false)&&(p.is_active!==false)&&(movementModuleFilter==='all'||p.module_id===movementModuleFilter)).sort((a:any,b:any)=>String(a.name_es||a.name||'').localeCompare(String(b.name_es||b.name||''),'es'));
 async function saveMovementSheet(){
  // Validar TODAS las cantidades antes de enviar cualquier movimiento.
  // Se envían en una sola petición para evitar que un fallo deje media hoja guardada.
  const changes=movementProducts
   .map((product:any)=>({product,raw:movementDrafts[product.id]?.exit||'',qty:Number(movementDrafts[product.id]?.exit||0)}))
   .filter((x:any)=>String(x.raw).trim()!=='' && x.qty>0);
  if(!changes.length){setNotice({type:'info',text:'Escribe una cantidad en Salida para al menos un producto.'});return}
  for(const item of changes){
   const product=item.product;const before=Number(product.stock||0);
   let validationError='';
   if(!Number.isFinite(item.qty)||item.qty<=0)validationError=`La salida de ${product.name_es||product.name} debe ser mayor que cero.`;
   else if(item.qty>before)validationError=`La salida de ${product.name_es||product.name} supera la existencia disponible (${before} ${product.unit||''}).`;
   else if(!product.unit_id)validationError=`El producto ${product.name_es||product.name} no tiene unit_id configurado. Corrige la unidad del producto antes de registrar la salida.`;
   if(validationError){setNotice({type:'error',text:validationError});return}
  }
  setBusy(true);setNotice(null);try{
   const payloads=changes.map((item:any)=>{
    const product=item.product;const qty=item.qty;const before=Number(product.stock||0);const after=before-qty;
    return {product_id:product.id,movement_type:'manual_out',direction:'out',quantity:qty,unit_id:product.unit_id,quantity_base:qty,quantity_before:before,quantity_after:after,reason:'Salida planificada desde hoja diaria',notes:`Hoja de salida para empleado · ${today()}`,user_id:session.user.id,created_by:session.user.id};
   });
   const {error:insertError}=await supabase.from('inventory_movements').insert(payloads);
   if(insertError)throw new Error(insertError.message);

   // Recargar inventario e historial desde la base de datos; el trigger de Supabase
   // es el responsable de descontar el stock dentro de la transacción del movimiento.
   const {data:prods,error:prodsError}=await supabase.from('products').select('id,name,name_es,name_en,unit_id,unit,stock,module_id,active,is_active').eq('active',true).order('name');
   if(prodsError)throw new Error(`Los movimientos se insertaron, pero no se pudo verificar el inventario: ${prodsError.message}`);
   setLookupProducts(prods||[]);
   await loadRows();
   const mismatch=changes.find((item:any)=>{
    const refreshed=(prods||[]).find((p:any)=>p.id===item.product.id);
    return !refreshed || Number(refreshed.stock)!==Number(item.product.stock||0)-item.qty;
   });
   setMovementDrafts({});
   if(mismatch){
    setNotice({type:'error',text:`Las salidas se guardaron en el historial, pero el stock de “${mismatch.product.name_es||mismatch.product.name}” no quedó con la cantidad esperada. No vuelvas a guardar esa salida. Hay que revisar el trigger de Supabase para evitar que el stock quede incorrecto.`});
   }else{
    setNotice({type:'ok',text:`Se guardaron ${changes.length} salida(s) en el historial y se verificó que el inventario quedó descontado correctamente. Ya puedes imprimir o descargar la hoja.`});
   }
  }catch(e:any){setNotice({type:'error',text:'No se pudieron guardar las salidas. '+(e.message||'Error desconocido')+' Si la conexión se interrumpió, actualiza el historial antes de volver a intentarlo.'})}finally{setBusy(false)}
 }
