  const html=`<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40"><head><meta charset="UTF-8"><!--[if gte mso 9]><xml><x:ExcelWorkbook><x:ExcelWorksheets><x:ExcelWorksheet><x:Name>Hoja de salidas</x:Name><x:WorksheetOptions><x:DisplayGridlines/></x:WorksheetOptions></x:ExcelWorksheet></x:ExcelWorksheets></x:ExcelWorkbook></xml><![endif]--><style>body{font-family:Arial,sans-serif}h1{font-size:18pt}table{border-collapse:collapse;width:100%}th,td{border:1px solid #999;padding:8px;text-align:left}th{background:#f2f2f2;font-weight:bold}.salida{border-left:3px solid #f28c28;border-right:3px solid #f28c28;text-align:center;min-width:100px}</style></head><body><h1>HOJA DE SALIDAS DEL INVENTARIO</h1><p>Inventario: <b>${escapeHtml(selectedModuleName)}</b> &nbsp; Fecha: <b>${escapeHtml(today().split('-').reverse().join('/'))}</b></p><table><thead><tr><th>Producto</th><th>Cantidad</th><th class="salida">Salida</th><th>Total</th></tr></thead><tbody>${rowsHtml}</tbody></table><p>Preparado por: __________________________ &nbsp;&nbsp;&nbsp; Recibido por / Empleado: __________________________</p></body></html>`;
