 async function removeSavedMovement(row:any){
  if(!isAdmin){setNotice({type:'error',text:'Solo el superadministrador puede eliminar movimientos.'});return}
  if(!window.confirm('¿Eliminar este movimiento del historial y revertir su efecto en el stock? Esta acción se registrará como eliminación definitiva.'))return;
  setBusy(true);setNotice(null);
  try{
   const {error}=await supabase.rpc('delete_inventory_movement_reversibly',{p_movement_id:row.id});
   if(error)throw new Error(error.message.includes('Could not find the function')||error.message.includes('does not exist')?'Falta instalar la función SQL para eliminar movimientos de forma segura. Ejecuta supabase/delete_inventory_movement_reversibly.sql en Supabase SQL Editor y vuelve a intentarlo.':error.message);
   const {data:prods,error:prodsError}=await supabase.from('products').select('id,name,name_es,name_en,unit_id,unit,stock,module_id,active,is_active').eq('active',true).order('name');
   if(prodsError)throw new Error('El movimiento se eliminó y se revirtió el stock, pero no se pudo recargar la lista de productos: '+prodsError.message);
   setLookupProducts(prods||[]);await loadRows();setNotice({type:'ok',text:'Movimiento eliminado y efecto en existencias revertido correctamente.'});
  }catch(e:any){setNotice({type:'error',text:'No se pudo eliminar el movimiento: '+(e.message||'Error desconocido')})}finally{setBusy(false)}
 }
